@app.cell
def _(beta):
    def ngram_counts(seq, k):
        """Counts of every 2**k pattern in a size-k sliding window."""
        n_windows = len(seq) - k + 1
        counts = [0] * (2**k)
        for i in range(n_windows):
            idx = 0
            for j in range(k):
                idx = (idx << 1) | seq[i + j]
            counts[idx] += 1
        return counts, n_windows

    def ngram_test(seq, k, lo=0.05, hi=0.95):
        """Beta-binomial test per pattern; pass if inside the 90% interval.

        Under pure randomness a size-k pattern appears with probability
        p = 1/2**k. We model that null proportion with a Beta distribution whose
        pseudo-counts are the expected counts (a = N*p, b = N*(1-p)), then flag
        any pattern whose observed share falls outside the central 90% interval.
        """
        counts, N = ngram_counts(seq, k)
        p = 1 / 2**k
        a, b = N * p, N * (1 - p)
        lo_q, hi_q = beta.ppf(lo, a, b), beta.ppf(hi, a, b)
        rows = []
        for pat, c in enumerate(counts):
            obs = c / N if N else 0.0
            rows.append(
                {
                    "label": format(pat, f"0{k}b"),
                    "count": c,
                    "expected": N * p,
                    "quantile": float(beta.cdf(obs, a, b)) if N else 0.0,
                    "passed": bool(lo_q <= obs <= hi_q) if N else True,
                }
            )
        return rows, N, (a, b), (lo_q, hi_q)

    return (ngram_test,)


