@app.cell(hide_code=True)
def _(beta, mo, ngram_test, np, plt, seq):
    def dist_chart(k, title):
        if len(seq) < k + 2:
            return mo.md(f"*Flip at least {k + 2} coins for the {k}-gram distribution.*")
        rows, N, (a, b), (lo_q, hi_q) = ngram_test(seq, k)
        # Zoom the x-axis to where the mass and the most extreme pattern land.
        max_obs = max(r["count"] / N for r in rows)
        hi_x = min(1.0, max(hi_q * 1.5, max_obs * 1.2, 0.05))
        xs = np.linspace(0, hi_x, 400)
        fig, ax = plt.subplots(figsize=(7, 2.3))
        ax.plot(xs, beta.pdf(xs, a, b), color="#2563eb", lw=2, label="if random")
        ax.axvspan(lo_q, hi_q, color="#2563eb", alpha=0.08, label="90% interval")
        for r in rows:
            obs = r["count"] / N
            ax.axvline(
                obs,
                color="#dc2626" if not r["passed"] else "#111",
                ls=":",
                lw=1.5,
                alpha=0.9 if not r["passed"] else 0.4,
            )
        ax.set_yticks([])
        ax.set_xlabel("share of each pattern")
        ax.set_title(title)
        for s in ("top", "right", "left"):
            ax.spines[s].set_visible(False)
        ax.legend(loc="upper right", fontsize=8, frameon=False)
        fig.tight_layout()
        return fig

    return (dist_chart,)


