@app.cell(hide_code=True)
def _(mo, ngram_test, plt, seq):
    def bar_chart(k, title):
        if len(seq) < k + 2:
            return mo.md(f"*Flip at least {k + 2} coins for the {k}-gram counts.*")
        rows, N, _, _ = ngram_test(seq, k)
        labels = [r["label"] for r in rows]
        counts = [r["count"] for r in rows]
        expected = N / 2**k
        colors = ["#dc2626" if not r["passed"] else "#2563eb" for r in rows]
        fig, ax = plt.subplots(figsize=(9, 2.6))
        ax.bar(range(len(counts)), counts, color=colors)
        ax.axhline(expected, color="#111", ls="--", lw=1.5, label="if random")
        ax.set_xticks(range(len(labels)))
        ax.set_xticklabels(labels, rotation=90, fontsize=6, family="monospace")
        ax.set_ylabel("count")
        ax.set_title(title)
        ax.spines["top"].set_visible(False)
        ax.spines["right"].set_visible(False)
        ax.legend(loc="upper right", fontsize=8, frameon=False)
        fig.tight_layout()
        return fig

    return (bar_chart,)


