@app.cell(hide_code=True)
def _(mo, ngram_test, seq):
    # Verdict — how many patterns look non-random across every window size?
    def _verdict():
        if len(seq) < 10:
            return mo.md("*Flip ~30+ coins for a verdict.*")
        total = fails = 0
        for k in range(1, 6):
            if len(seq) < k + 1:
                continue
            rows, _, _, _ = ngram_test(seq, k)
            total += len(rows)
            fails += sum(1 for r in rows if not r["passed"])
        share = fails / total if total else 0
        if share > 0.2:
            msg = (
                f"### 🧑 Looks human — {fails}/{total} tests failed\n\n"
                "A machine typically fails only a handful (~10%, the false-positive "
                "rate of a 90% interval). People alternate too much (`01`/`10`) and "
                "shy away from long runs of the same value."
            )
        else:
            msg = (
                f"### 🤖 Indistinguishable from random — {fails}/{total} tests failed\n\n"
                "That is about what you'd expect from a real random source. "
                "Impressively machine-like!"
            )
        return mo.md(msg)

    _verdict()
    return


@app.cell(hide_code=True)
def _(anywidget, traitlets):
    class CoinFlip(anywidget.AnyWidget):
        """A tiny 0/1 pad. Click a button (or click once, then tap 0/1 keys)."""

        _esm = """
        function render({ model, el }) {
          el.innerHTML = "";
          const root = document.createElement("div");
          root.className = "coinflip";
          root.tabIndex = 0;

          const status = document.createElement("div");
          status.className = "cf-status";

          const btns = document.createElement("div");
          btns.className = "cf-btns";
          const b0 = document.createElement("button"); b0.textContent = "0"; b0.className = "cf-bit";
          const b1 = document.createElement("button"); b1.textContent = "1"; b1.className = "cf-bit";
          const reset = document.createElement("button"); reset.textContent = "Reset"; reset.className = "cf-reset";
          btns.append(b0, b1, reset);

          // The stream of recent flips, newest on the right (like the blog post).
          const tape = document.createElement("div");
          tape.className = "cf-tape";

          const counter = document.createElement("div");
          counter.className = "cf-counter";

          root.append(status, btns, tape, counter);
          el.append(root);

          function append(bit) {
            const seq = model.get("sequence").slice();
            seq.push(bit);
            model.set("sequence", seq);
            model.save_changes();
          }
          function pop() {
            const seq = model.get("sequence").slice();
            if (seq.length === 0) return;
            seq.pop();
            model.set("sequence", seq);
            model.save_changes();
          }
          function clear() {
            model.set("sequence", []);
            model.save_changes();
          }
          function updateCounter() {
            const seq = model.get("sequence");
            const ones = seq.reduce((a, b) => a + b, 0);
            counter.textContent = `${seq.length} flips · ${seq.length - ones} zeros · ${ones} ones`;
          }
          function updateTape() {
            const seq = model.get("sequence");
            const last = seq.slice(-20);
            tape.innerHTML = "";
            if (last.length === 0) {
              const hint = document.createElement("span");
              hint.className = "cf-tape-empty";
              hint.textContent = "your flip stream shows up here…";
              tape.append(hint);
              return;
            }
            last.forEach((b, i) => {
              const chip = document.createElement("span");
              chip.className = "cf-chip cf-chip-" + b + (i === last.length - 1 ? " cf-chip-new" : "");
              chip.textContent = b;
              tape.append(chip);
            });
          }
          function setActive(on) {
            root.classList.toggle("is-active", on);
            status.textContent = on
              ? "● listening — tap 0 / 1 (⌫ undo, r resets)"
              : "click a button to start logging keys";
          }

          b0.addEventListener("click", () => { append(0); root.focus(); });
          b1.addEventListener("click", () => { append(1); root.focus(); });
          reset.addEventListener("click", () => { clear(); root.focus(); });

          // Keyboard capture is gated by focus: keys only count while the pad
          // holds focus, which a click puts it into.
          root.addEventListener("focusin", () => setActive(true));
          root.addEventListener("focusout", () => setActive(false));
          root.addEventListener("keydown", (e) => {
            if (e.key === "0" || e.key === "1") {
              e.preventDefault(); e.stopPropagation();
              append(parseInt(e.key, 10));
            } else if (e.key === "Backspace" || e.key === "Delete") {
              e.preventDefault(); e.stopPropagation();
              pop();
            } else if (e.key === "r" || e.key === "R") {
              e.preventDefault(); clear();
            }
          });

          model.on("change:sequence", () => { updateCounter(); updateTape(); });
          updateCounter();
          updateTape();
          setActive(false);
        }
        export default { render };
        """

