@app.cell(hide_code=True)
def _(mo):
    # marimo does not re-run cells on a *backend* write to a widget trait, only on
    # real frontend interactions. This observer bridges every change to the pad's
    # sequence (whether you flip, or Simulate writes into it) into reactive state,
    # so the widget stays the single source of truth and the charts always follow.
    get_seq, set_seq = mo.state([])
    return get_seq, set_seq


