    sim_btn = mo.ui.run_button(label="🎲 Simulate random flips")
    mo.vstack(
        [
            mo.md("### Let a machine flip instead"),
            mo.md(
                "Fill the pad with real randomness — the charts update only when you press the button."
            ),
            mo.hstack([sim_n, sim_btn], justify="start", gap=1, align="center"),
        ]
    )
    return sim_btn, sim_n


